const CAMPAIGN_STATUSES = ['ACTIVE', 'PAUSED', 'CLOSED'] as const;

function fmt(date: string) {
  return new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

function fmtTime(date: string) {
  return new Date(date).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

function formatBudget(min: number, max: number) {
  if (min === 0 && max === 0) return 'Non-monetary';
  const f = (n: number) => `NPR ${n.toLocaleString()}`;
  return min === max ? f(min) : `${f(min)} – ${f(max)}`;
}

function formatRequirementBudget(r: { budgetType: string; budgetFixed: number | null; budgetMin: number | null; budgetMax: number | null }) {
  const f = (n: number) => `NPR ${n.toLocaleString()}`;
  if (r.budgetType === 'FIXED')  return f(r.budgetFixed ?? 0);
  if (r.budgetType === 'RANGE')  return `${f(r.budgetMin ?? 0)} – ${f(r.budgetMax ?? 0)}`;
  return 'Negotiable';
}

function appStatusIcon(status: string) {
  if (status === 'ACCEPTED')    return <CheckCircle2 size={14} className="text-green-500" />;
  if (status === 'REJECTED')    return <XCircle      size={14} className="text-red-400"   />;
  if (status === 'EXPIRED')     return <Clock        size={14} className="text-gray-400"  />;
  if (status === 'SHORTLISTED') return <Star         size={14} className="text-blue-500"  />;
  return                                <Hourglass    size={14} className="text-amber-500" />;
}

function appStatusBadge(status: string): string {
  const s = status.toLowerCase();
  if (s === 'accepted')    return 'active';
  if (s === 'rejected')    return 'cancelled';
  if (s === 'expired')     return 'expired';
  if (s === 'shortlisted') return 'shortlisted';
  return 'pending';
}

function parseDeliverableUrls(raw?: string | null): string[] {
  if (!raw) return [];
  return raw.split(/[\n,]/).map((s) => s.trim()).filter(Boolean);
}

const DIRECT_VIDEO_EXTENSIONS = /\.(mp4|mov|m4v|webm|m3u8)(\?.*)?$/i;

// A raw video file URL (Cloudinary, S3, etc.) can play directly in an
// in-page <video> element — a YouTube/Google Drive share link is a *page*,
// not a video file, and has to open in a new tab instead.
function isDirectVideoUrl(url: string): boolean {
  if (DIRECT_VIDEO_EXTENSIONS.test(url)) return true;
  try {
    const { hostname, pathname } = new URL(url);
    return hostname.endsWith('res.cloudinary.com') && pathname.includes('/video/');
  } catch {
    return false;
  }
}

// ── Video player modal ──────────────────────────────────────────────────────

function VideoPlayerModal({ video, onClose }: { video: { url: string; label: string } | null; onClose: () => void }) {
  if (!video) return null;
  return (
    <div className="fixed inset-0 z-50 bg-black/70 flex items-center justify-center p-6" onClick={onClose}>
      <div className="bg-black rounded-xl overflow-hidden max-w-3xl w-full" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-4 py-2 bg-gray-900">
          <p className="text-sm text-white font-medium truncate">{video.label}</p>
          <button onClick={onClose} className="text-gray-300 hover:text-white text-lg leading-none px-1">✕</button>
        </div>
        <video src={video.url} controls autoPlay className="w-full max-h-[75vh] bg-black" />
      </div>
    </div>
  );
}

// ── Timeline ──────────────────────────────────────────────────────────────────

function buildTimeline(campaign: ApiCampaignDetail) {
  const events: { date: string; label: string; sub?: string; color: string }[] = [];

  events.push({
    date:  campaign.createdAt,
    label: 'Event created',
    sub:   `by ${displayBusinessName(campaign.business.businessName)}`,
    color: 'bg-indigo-500',
  });

  const byDate = [...campaign.applications].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
  );

  for (const app of byDate) {
    const name = app.creator.fullName ?? displayEmailOrPhone(app.creator.user.email);
    events.push({
      date:  app.createdAt,
      label: `${name} applied`,
      sub:   `NPR ${app.proposedRate.toLocaleString()} · ${app.timeline}`,
      color: 'bg-gray-400',
    });
    if (app.status !== 'PENDING') {
      events.push({
        date:  app.updatedAt,
        label: app.status === 'ACCEPTED' ? `${name} accepted`
          : app.status === 'EXPIRED' ? `${name}'s proposal expired`
          : `${name} rejected`,
        color: app.status === 'ACCEPTED' ? 'bg-green-500' : app.status === 'EXPIRED' ? 'bg-gray-400' : 'bg-red-400',
      });
    }
    if (app.workStatus === 'IN_PROGRESS') {
      events.push({ date: app.updatedAt, label: `${name} started work`, color: 'bg-blue-500' });
    }
    if (app.workStatus === 'SUBMITTED') {
      events.push({ date: app.updatedAt, label: `${name} submitted deliverables`, color: 'bg-purple-500' });
    }
    if (app.workStatus === 'APPROVED') {
      events.push({ date: app.updatedAt, label: `Work approved — ${name}`, color: 'bg-green-600' });
    }
  }

  events.push({
    date:  campaign.updatedAt,
    label: `Status: ${campaign.status}`,
    sub:   'Current event status',
    color: campaign.status === 'ACTIVE' ? 'bg-emerald-500' : campaign.status === 'PAUSED' ? 'bg-orange-400' : 'bg-gray-500',
  });

  return events
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
    .filter((e, i, arr) => i === 0 || e.date !== arr[i - 1]!.date || e.label !== arr[i - 1]!.label);
}

// ── Application row ───────────────────────────────────────────────────────────

function ApplicationRow({ app, commissionRate, roleName }: {
  app: ApiApplication;
  commissionRate?: number | null;
  // Category name of the requirement app.requirementId points to — undefined
  // for simple single-category campaigns, where there's nothing to label.
  roleName?: string;
}) {
  const [expanded, setExpanded] = useState(false);
  const [playingVideo, setPlayingVideo] = useState<{ url: string; label: string } | null>(null);
  const name = app.creator.fullName ?? displayEmailOrPhone(app.creator.user.email);
  const initials = name.slice(0, 2).toUpperCase();

  return (
    <div className="border border-gray-100 rounded-xl overflow-hidden">
      <div
        className="flex items-center gap-3 px-4 py-3 hover:bg-gray-50 cursor-pointer transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        {app.creator.avatarUrl ? (
          <img src={app.creator.avatarUrl} alt={name} className="w-8 h-8 rounded-full object-cover flex-shrink-0" />
        ) : (
          <Avatar initials={initials} size="sm" />
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <p className="font-medium text-gray-900 text-sm truncate">{name}</p>
            {roleName && (
              <span className="text-[10px] font-medium bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded-full flex-shrink-0">{roleName}</span>
            )}
          </div>
          <p className="text-xs text-gray-500 truncate">{displayEmailOrPhone(app.creator.user.email)}</p>
        </div>
        <div className="flex items-center gap-3 flex-shrink-0">
          <div className="text-right">
            <span className="text-sm font-semibold text-gray-800">NPR {app.proposedRate.toLocaleString()}</span>
            {!!commissionRate && (
              <p className="text-[10px] text-gray-400 leading-none mt-0.5">
                +{commissionRate}% fee · business pays {Math.round(app.proposedRate * (1 + commissionRate / 100)).toLocaleString()}
              </p>
            )}
          </div>
          <div className="flex items-center gap-1">
            {appStatusIcon(app.status)}
            <StatusBadge status={appStatusBadge(app.status)} />
          </div>
          {app.paymentStatus === 'RELEASED' && (
            <span className="flex items-center gap-1 text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-200">
              <CheckCircle2 size={12} /> Paid
            </span>
          )}
          <span className="text-xs text-gray-400">{fmt(app.createdAt)}</span>
        </div>
      </div>
      {expanded && (
        <div className="px-4 pb-4 pt-1 bg-gray-50 border-t border-gray-100 space-y-3">
          <div>
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1">Cover Letter</p>
            <p className="text-sm text-gray-700 leading-relaxed">{app.coverLetter}</p>
          </div>
          <div className="flex flex-wrap gap-4 text-xs text-gray-500">
            <span><span className="font-medium text-gray-700">Timeline:</span> {app.timeline}</span>
            {app.creator.location && <span><span className="font-medium text-gray-700">Location:</span> {app.creator.location}</span>}
            {app.portfolioUrl && (
              <a href={app.portfolioUrl} target="_blank" rel="noopener noreferrer" className="text-indigo-600 hover:underline font-medium">
                Portfolio
              </a>
            )}
          </div>
          {app.creator.categories.length > 0 && (
            <div className="flex flex-wrap gap-1">
              {app.creator.categories.map((c) => (
                <span key={c} className="text-xs bg-indigo-50 text-indigo-700 px-2 py-0.5 rounded-full">{c}</span>
              ))}
            </div>
          )}
          {((app.deliverableVideos?.length ?? 0) > 0 || (app.deliverableFiles?.length ?? 0) > 0 || app.deliverableUrls) && (
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1">Submitted Deliverables</p>
              {(app.deliverableFiles?.filter((f) => f.fileType === 'IMAGE').length ?? 0) > 0 && (
                <div className="flex flex-wrap gap-2 mb-2">
                  {app.deliverableFiles!.filter((f) => f.fileType === 'IMAGE').map((f) => (
                    <button
                      key={f.id}
                      onClick={(e) => { e.stopPropagation(); window.open(f.url, '_blank', 'noopener,noreferrer'); }}
                      className="block w-14 h-14 rounded-md overflow-hidden border border-gray-200 hover:opacity-80"
                      title={f.originalFileName}
                    >
                      <img src={f.url} alt={f.originalFileName} className="w-full h-full object-cover" />
                    </button>
                  ))}
                </div>
              )}
              <div className="flex flex-col gap-1">
                {app.deliverableVideos?.map((v) => (
                  <button
                    key={v.publicId}
                    onClick={(e) => { e.stopPropagation(); setPlayingVideo({ url: v.url, label: v.label }); }}
                    className="text-indigo-600 hover:underline font-medium text-sm flex items-center gap-1.5 text-left"
                  >
                    <Video size={13} /> {v.label} ({Math.round(v.durationSec)}s)
                  </button>
                ))}
                {app.deliverableFiles?.filter((f) => f.fileType === 'DOCUMENT').map((f) => (
                  <a
                    key={f.id}
                    href={f.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-indigo-600 hover:underline font-medium text-sm flex items-center gap-1.5 text-left truncate"
                  >
                    <FileText size={13} className="flex-shrink-0" /> {f.originalFileName}
                  </a>
                ))}
                {parseDeliverableUrls(app.deliverableUrls).map((url) => (
                  isDirectVideoUrl(url) ? (
                    <button
                      key={url}
                      onClick={(e) => { e.stopPropagation(); setPlayingVideo({ url, label: url }); }}
                      className="text-indigo-600 hover:underline font-medium text-sm flex items-center gap-1.5 text-left truncate"
                    >
                      <Video size={13} className="flex-shrink-0" /> {url}
                    </button>
                  ) : (
                    <a
                      key={url}
                      href={url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-indigo-600 hover:underline font-medium text-sm truncate"
                    >
                      {url}
                    </a>
                  )
                ))}
              </div>
            </div>
          )}
          <div className="flex flex-wrap gap-4 text-xs text-gray-500 pt-1 border-t border-gray-200">
            <span><span className="font-medium text-gray-700">Work status:</span> {app.workStatus}</span>
            <span><span className="font-medium text-gray-700">Payment status:</span> {app.paymentStatus}</span>
          </div>
        </div>
      )}
      <VideoPlayerModal video={playingVideo} onClose={() => setPlayingVideo(null)} />
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────

export function CampaignDetail() {
  const { id }     = useParams<{ id: string }>();
  const navigate   = useNavigate();
  const [statusChanging, setStatusChanging] = useState(false);
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);
  const [approving, setApproving] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [rejecting, setRejecting] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);

  const { data, loading, error, refetch } = useApi(() => api.admin.campaignDetail(id!));
  const campaign = data?.data ?? null;

  function showToast(msg: string, ok = true) {
    setToast({ msg, ok });
    setTimeout(() => setToast(null), 3000);
  }

  async function handleStatusChange(newStatus: string) {
    if (!campaign || newStatus === campaign.status) return;
    setStatusChanging(true);
    try {
      await api.admin.updateCampaignStatus(id!, newStatus);
      showToast(`Status updated to ${newStatus}`);
      refetch();
    } catch (e) {
      showToast((e as Error).message ?? 'Failed to update status.', false);
    } finally {
      setStatusChanging(false);
    }
  }

  async function handleApprove() {
    setApproving(true);
    try {
      await api.admin.approveCampaign(id!);
      showToast('Event approved and is now live.');
      refetch();
    } catch (e) {
      showToast((e as Error).message ?? 'Failed to approve event.', false);
    } finally {
      setApproving(false);
    }
  }

  async function handleReject() {
    if (!rejectReason.trim()) return;
    setRejecting(true);
    try {
      await api.admin.rejectCampaign(id!, rejectReason.trim());
      showToast('Event rejected.');
      setShowRejectModal(false);
      setRejectReason('');
      refetch();
    } catch (e) {
      showToast((e as Error).message ?? 'Failed to reject event.', false);
    } finally {
      setRejecting(false);
    }
  }

  if (loading) {
    return (
      <div className="space-y-4">
        <div className="h-8 w-40 bg-gray-100 rounded animate-pulse" />
        <div className="h-48 bg-gray-100 rounded-xl animate-pulse" />
        <div className="h-64 bg-gray-100 rounded-xl animate-pulse" />
      </div>
    );
  }

  if (error || !campaign) {
    return (
      <div className="p-6 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm">
        {error ?? 'Event not found.'}
      </div>
    );
  }

  const acceptedCount = campaign.applications.filter((a) => a.status === 'ACCEPTED').length;
  const pendingCount  = campaign.applications.filter((a) => a.status === 'PENDING').length;
  const rejectedCount = campaign.applications.filter((a) => a.status === 'REJECTED').length;
  const timeline      = buildTimeline(campaign);
  const isEvent       = campaign.campaignType === 'OPEN_EVENT';

  return (
    <div className="space-y-6">

      {/* Back + title row */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-start gap-3">
          <button
            onClick={() => navigate('/campaigns')}
            className="mt-0.5 p-1.5 rounded-lg hover:bg-gray-100 text-gray-500 hover:text-gray-700 transition-colors flex-shrink-0"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-bold text-gray-900">{campaign.title}</h1>
              {campaign.isFeatured && (
                <span className="flex items-center gap-1 text-xs font-medium bg-amber-50 text-amber-700 px-2 py-0.5 rounded-full border border-amber-200">
                  <Star size={11} /> Featured
                </span>
              )}
              <StatusBadge status={campaign.status === 'PENDING_APPROVAL' ? 'pending' : campaign.status.toLowerCase()} />
            </div>
            <p className="text-sm text-gray-500 mt-0.5">{displayBusinessName(campaign.business.businessName)} · {isEvent ? 'Open Event' : 'Paid Event'}</p>
          </div>
        </div>

        {/* Status management */}
        <div className="flex items-center gap-2 flex-shrink-0">
          <button
            onClick={() => setShowEditModal(true)}
            className="px-3 py-1.5 text-xs font-medium bg-white border border-gray-200 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
          >
            Edit
          </button>
          {campaign.status === 'PENDING_APPROVAL' ? (
            <>
              <button
                onClick={handleApprove}
                disabled={approving}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-60 transition-colors"
              >
                <CheckCircle2 size={14} />
                {approving ? 'Approving…' : 'Approve'}
              </button>
              <button
                onClick={() => setShowRejectModal(true)}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-white border border-red-200 text-red-600 rounded-lg hover:bg-red-50 transition-colors"
              >
                <XCircle size={14} />
                Reject
              </button>
            </>
          ) : campaign.status === 'EXPIRED' || campaign.status === 'CANCELLED' ? (
            <>
              <span className="text-xs text-gray-500">Status:</span>
              <StatusBadge status={campaign.status.toLowerCase()} />
            </>
          ) : (
            <>
              <span className="text-xs text-gray-500">Status:</span>
              <select
                value={campaign.status}
                onChange={(e) => handleStatusChange(e.target.value)}
                disabled={statusChanging}
                className="text-xs font-medium border border-gray-200 rounded-lg px-2.5 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-60"
              >
                {CAMPAIGN_STATUSES.map((s) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </>
          )}
        </div>
      </div>

      <ConfirmModal
        open={showRejectModal}
        title="Reject this event?"
        body="The business will be notified with the reason below. This cannot be undone."
        confirmLabel="Reject event"
        variant="danger"
        loading={rejecting}
        confirmDisabled={!rejectReason.trim()}
        extra={
          <textarea
            autoFocus
            rows={3}
            value={rejectReason}
            onChange={(e) => setRejectReason(e.target.value)}
            placeholder="Reason for rejection (shown to the business)…"
            className="w-full text-sm border border-gray-200 rounded-xl px-3 py-2 focus:outline-none focus:ring-2 focus:ring-red-400 resize-none"
          />
        }
        onConfirm={handleReject}
        onCancel={() => { setShowRejectModal(false); setRejectReason(''); }}
      />

      {showEditModal && (
        <EditEventModal
          campaignId={id!}
          onClose={() => setShowEditModal(false)}
          onSaved={() => { setShowEditModal(false); showToast('Event updated.'); refetch(); }}
        />
      )}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">

        {/* Left column */}
        <div className="xl:col-span-2 space-y-6">

          {/* Info card */}
          <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-5">
            <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
              <FileText size={15} className="text-gray-400" /> Event Details
            </h2>

            {/* Key stats */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {[
                { icon: DollarSign, label: 'Budget',   value: formatBudget(campaign.budgetMin, campaign.budgetMax) },
                { icon: Calendar,   label: 'Deadline', value: fmt(campaign.deadline) },
                { icon: Users,      label: 'Needed',   value: `${campaign.creatorsNeeded} creator${campaign.creatorsNeeded !== 1 ? 's' : ''}` },
                { icon: Target,     label: 'Platform', value: campaign.platforms.length ? campaign.platforms.join(', ') : '—' },
                ...(campaign.commissionRate != null
                  ? [{ icon: Wallet, label: 'Platform Fee', value: `${campaign.commissionRate}% (business pays on top)` }]
                  : []),
              ].map(({ icon: Icon, label, value }) => (
                <div key={label} className="bg-gray-50 rounded-lg px-3 py-3">
                  <div className="flex items-center gap-1.5 text-gray-400 mb-1">
                    <Icon size={13} />
                    <span className="text-xs">{label}</span>
                  </div>
                  <p className="text-sm font-semibold text-gray-900">{value}</p>
                </div>
              ))}
            </div>

            {/* Meta rows */}
            <div className="space-y-2 text-sm">
              {campaign.category && (
                <div className="flex gap-2">
                  <span className="text-gray-400 w-24 flex-shrink-0">Category</span>
                  <span className="text-gray-800">{campaign.category}</span>
                </div>
              )}
              {campaign.location && (
                <div className="flex gap-2 items-start">
                  <span className="text-gray-400 w-24 flex-shrink-0 flex items-center gap-1"><MapPin size={11} /> Location</span>
                  <span className="text-gray-800">{campaign.location}</span>
                </div>
              )}
              {isEvent && campaign.venue && (
                <div className="flex gap-2">
                  <span className="text-gray-400 w-24 flex-shrink-0">Venue</span>
                  <span className="text-gray-800">{campaign.venue}</span>
                </div>
              )}
              {isEvent && campaign.eventDate && (
                <div className="flex gap-2">
                  <span className="text-gray-400 w-24 flex-shrink-0">Event date</span>
                  <span className="text-gray-800">{fmt(campaign.eventDate)}</span>
                </div>
              )}
              {campaign.paymentType && (
                <div className="flex gap-2">
                  <span className="text-gray-400 w-24 flex-shrink-0">Payment</span>
                  <span className="text-gray-800">{campaign.paymentType}</span>
                </div>
              )}
              <div className="flex gap-2">
                <span className="text-gray-400 w-24 flex-shrink-0">Created</span>
                <span className="text-gray-800">{fmt(campaign.createdAt)}</span>
              </div>
            </div>

            {/* Goals */}
            {campaign.goals.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Goals</p>
                <div className="flex flex-wrap gap-1.5">
                  {campaign.goals.map((g) => (
                    <span key={g} className="text-xs bg-indigo-50 text-indigo-700 px-2.5 py-1 rounded-full">{g}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Benefits (events) */}
            {isEvent && campaign.benefits.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Creator Benefits</p>
                <div className="flex flex-wrap gap-1.5">
                  {campaign.benefits.map((b) => (
                    <span key={b} className="text-xs bg-green-50 text-green-700 px-2.5 py-1 rounded-full">{b}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Target Audience */}
            {!!campaign.targetAudience?.length && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Target Audience</p>
                <div className="flex flex-wrap gap-1.5">
                  {campaign.targetAudience.map((a) => (
                    <span key={a} className="text-xs bg-purple-50 text-purple-700 px-2.5 py-1 rounded-full">{a}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Hashtags */}
            {!!campaign.hashtags?.length && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Hashtags</p>
                <div className="flex flex-wrap gap-1.5">
                  {campaign.hashtags.map((h) => (
                    <span key={h} className="text-xs bg-blue-50 text-blue-700 px-2.5 py-1 rounded-full">#{h.replace(/^#/, '')}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Description */}
            {campaign.description && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Description</p>
                <p className="text-sm text-gray-700 leading-relaxed whitespace-pre-line">{campaign.description}</p>
              </div>
            )}

            {/* Sample Caption */}
            {campaign.sampleCaption && (
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Sample Caption</p>
                <p className="text-sm text-gray-700 leading-relaxed italic">&ldquo;{campaign.sampleCaption}&rdquo;</p>
              </div>
            )}

            {/* Quick-create provenance */}
            {campaign.aiGenerated && (
              <div className="bg-indigo-50 border border-indigo-100 rounded-lg px-3 py-2.5 flex items-start gap-2">
                <FileText size={14} className="text-indigo-500 mt-0.5 flex-shrink-0" />
                <div className="text-xs text-indigo-700">
                  <span className="font-semibold">Created from a quick description</span>
                  {campaign.aiPrompt && <p className="text-indigo-600 mt-0.5">&ldquo;{campaign.aiPrompt}&rdquo;</p>}
                  {!!campaign.aiSuggestedCategories?.length && (
                    <p className="text-indigo-500 mt-1">
                      Also relevant: {campaign.aiSuggestedCategories.join(', ')}
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Roles Needed — multi-role campaigns only (§ CampaignRequirement),
              empty/absent for the simple single-category campaigns every
              existing campaign uses. */}
          {!!campaign.requirements?.length && (
            <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-4">
              <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
                <Layers size={15} className="text-gray-400" /> Roles Needed
              </h2>
              <div className="space-y-2">
                {campaign.requirements.map((r) => {
                  const accepted = r._count.applications;
                  const full = accepted >= r.quantity;
                  return (
                    <div key={r.id} className="flex items-center gap-3 bg-gray-50 rounded-lg px-3 py-2.5">
                      <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0"
                        style={{ backgroundColor: `${r.category.color}1A`, color: r.category.color }}>
                        <Users size={14} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-gray-900">{r.category.name}</p>
                        <p className="text-xs text-gray-400">{formatRequirementBudget(r)}</p>
                      </div>
                      <span className={`text-xs font-semibold px-2 py-1 rounded-full flex-shrink-0 ${full ? 'bg-green-50 text-green-700' : 'bg-gray-100 text-gray-600'}`}>
                        {accepted}/{r.quantity} filled
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Applications */}
          <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
                <Users size={15} className="text-gray-400" /> Applications
                <span className="font-normal text-gray-400">({campaign._count.applications})</span>
              </h2>
              <div className="flex gap-3 text-xs text-gray-500">
                <span className="text-green-600 font-medium">{acceptedCount} accepted</span>
                <span className="text-amber-500 font-medium">{pendingCount} pending</span>
                <span className="text-red-400 font-medium">{rejectedCount} rejected</span>
              </div>
            </div>

            {campaign.applications.length === 0 ? (
              <p className="text-sm text-gray-400 py-4 text-center">No applications yet.</p>
            ) : (
              <div className="space-y-2">
                {campaign.applications.map((app) => (
                  <ApplicationRow
                    key={app.id}
                    app={app}
                    commissionRate={campaign.commissionRate}
                    roleName={campaign.requirements?.find((r) => r.id === app.requirementId)?.category.name}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Right column */}
        <div className="space-y-6">

          {/* Business card */}
          <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-3">
            <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
              <Building2 size={15} className="text-gray-400" /> Business
            </h2>
            <div className="flex items-center gap-3">
              {campaign.business.logoUrl ? (
                <img src={campaign.business.logoUrl} alt={displayBusinessName(campaign.business.businessName)} className="w-10 h-10 rounded-lg object-cover" />
              ) : (
                <Avatar initials={displayBusinessName(campaign.business.businessName).slice(0, 2).toUpperCase()} size="sm" />
              )}
              <div className="min-w-0">
                <p className="font-semibold text-gray-900 text-sm truncate">{displayBusinessName(campaign.business.businessName)}</p>
                {campaign.business.website && (
                  <a href={campaign.business.website} target="_blank" rel="noopener noreferrer" className="text-xs text-indigo-600 hover:underline truncate block">
                    {campaign.business.website.replace(/^https?:\/\//, '')}
                  </a>
                )}
              </div>
            </div>
            {campaign.business.description && (
              <p className="text-xs text-gray-500 leading-relaxed line-clamp-3">{campaign.business.description}</p>
            )}
          </div>

          {/* Quick stats */}
          <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-3">
            <h2 className="text-sm font-semibold text-gray-900">Quick Stats</h2>
            {[
              { label: 'Total applications', value: campaign._count.applications },
              { label: 'Accepted',           value: acceptedCount },
              { label: 'Pending review',     value: pendingCount },
              { label: 'Rejected',           value: rejectedCount },
              { label: 'Slots needed',       value: campaign.creatorsNeeded },
              { label: 'Slots filled',       value: `${acceptedCount} / ${campaign.creatorsNeeded}` },
            ].map(({ label, value }) => (
              <div key={label} className="flex items-center justify-between">
                <span className="text-xs text-gray-500">{label}</span>
                <span className="text-sm font-semibold text-gray-900">{value}</span>
              </div>
            ))}
          </div>

          {/* Activity timeline */}
          <div className="bg-white border border-gray-200 rounded-xl p-5 space-y-4">
            <h2 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
              <Activity size={15} className="text-gray-400" /> Activity Timeline
            </h2>
            <div className="relative space-y-0">
              {timeline.map((event, i) => (
                <div key={i} className="flex gap-3 pb-4 last:pb-0">
                  <div className="flex flex-col items-center">
                    <div className={`w-2.5 h-2.5 rounded-full flex-shrink-0 mt-0.5 ${event.color}`} />
                    {i < timeline.length - 1 && <div className="w-px flex-1 bg-gray-100 mt-1" />}
                  </div>
                  <div className="pb-0 min-w-0">
                    <p className="text-xs font-medium text-gray-800 leading-snug">{event.label}</p>
                    {event.sub && <p className="text-xs text-gray-400 mt-0.5 truncate">{event.sub}</p>}
                    <p className="text-xs text-gray-300 mt-0.5">
                      <Clock size={10} className="inline mr-1" />{fmtTime(event.date)}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>

        </div>
      </div>

      {toast && (
        <div className={`fixed bottom-6 left-1/2 -translate-x-1/2 px-5 py-3 rounded-xl text-sm font-medium text-white shadow-lg z-50 ${toast.ok ? 'bg-gray-900' : 'bg-red-600'}`}>
          {toast.msg}
        </div>
      )}
    </div>
  );
}
